#!/usr/bin/env python3
"""
resolve_config.py — Resolutor del patrón 'Configurable Agent Skills'.
Permite leer y sobrescribir parámetros globales (FPS=30, resolución 1080x1920,
superficie #F8F7F4, voice_id y model_id de ElevenLabs) desde .agent/skills.config.yaml
y variables de entorno (.env) sin bifurcar los archivos SKILL.md originales.
"""

from __future__ import annotations
import json
import os
import re
import sys
from pathlib import Path
from typing import Any, Dict

ROOT_DIR = Path(__file__).resolve().parent.parent
CONFIG_PATH = ROOT_DIR / ".agent" / "skills.config.yaml"
ENV_PATH = ROOT_DIR / ".env"

DEFAULT_CONFIG: Dict[str, Any] = {
    "studio": {
        "name": "Antigravity Vector Video Studio",
        "fps": 30,
        "width": 1080,
        "height": 1920,
        "aspect_ratio": "9:16",
        "cross_dissolve_frames": 10,
    },
    "theme": {
        "surface": "#F8F7F4",
        "ink_primary": "#141413",
        "ink_secondary": "#575550",
        "accent_primary": "#D94E34",
        "accent_secondary": "#2563EB",
        "grid_line": "#E6E4DD",
        "zero_neon_policy": True,
    },
    "safe_zone": {
        "top_percent": 85,
        "bottom_reserved_px": 288,
        "horizontal_padding_px": 96,
        "min_headline_px": 64,
        "max_headline_words": 7,
        "min_label_px": 28,
        "max_label_words": 20,
    },
    "motion": {
        "forbid_css_transitions": True,
        "forbid_css_keyframes": True,
        "require_extrapolate_clamp": True,
        "springs": {
            "SPRING_SNAPPY": {"damping": 20, "stiffness": 200, "mass": 0.8},
            "SPRING_CAMERA": {"damping": 30, "stiffness": 90, "mass": 1.2},
        },
    },
    "elevenlabs": {
        "voice_id": "JBFqnCBsd6RMkjVDRZzb",
        "model_id": "eleven_multilingual_v2",
        "output_format": "mp3_44100_128",
        "apply_text_normalization": "on",
        "audit": {
            "min_words_per_sec": 2.0,
            "max_words_per_sec": 4.5,
            "max_leading_silence_ms": 200,
            "max_trailing_silence_ms": 500,
        },
    },
}


def parse_scalar(val: str) -> Any:
    val = val.strip()
    if (val.startswith('"') and val.endswith('"')) or (
        val.startswith("'") and val.endswith("'")
    ):
        return val[1:-1]
    if val.lower() == "true":
        return True
    if val.lower() == "false":
        return False
    try:
        if "." in val:
            return float(val)
        return int(val)
    except ValueError:
        return val


def load_simple_yaml(path: Path) -> Dict[str, Any]:
    """Parser ligero sin dependencias externas (PyYAML opcional)."""
    if not path.exists():
        return {}
    try:
        import yaml  # type: ignore

        with path.open("r", encoding="utf-8") as f:
            return yaml.safe_load(f) or {}
    except ImportError:
        result: Dict[str, Any] = {}
        stack: list[tuple[int, Dict[str, Any]]] = [(-1, result)]
        with path.open("r", encoding="utf-8") as f:
            for raw_line in f:
                line = re.sub(r"\s+#.*$", "", raw_line.rstrip())
                if not line.strip() or line.lstrip().startswith("#"):
                    continue
                indent = len(line) - len(line.lstrip(" "))
                key_part, _, val_part = line.strip().partition(":")
                key = key_part.strip()
                val_str = val_part.strip()
                while len(stack) > 1 and stack[-1][0] >= indent:
                    stack.pop()
                current_dict = stack[-1][1]
                if val_str == "":
                    new_dict: Dict[str, Any] = {}
                    current_dict[key] = new_dict
                    stack.append((indent, new_dict))
                else:
                    current_dict[key] = parse_scalar(val_str)
        return result


def load_dotenv(path: Path) -> Dict[str, str]:
    env_vars: Dict[str, str] = {}
    if not path.exists():
        return env_vars
    with path.open("r", encoding="utf-8") as f:
        for line in f:
            striped = line.strip()
            if not striped or striped.startswith("#") or "=" not in striped:
                continue
            k, _, v = striped.partition("=")
            env_vars[k.strip()] = v.strip().strip('"').strip("'")
    return env_vars


def deep_merge(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
    merged = dict(base)
    for k, v in override.items():
        if isinstance(v, dict) and isinstance(merged.get(k), dict):
            merged[k] = deep_merge(merged[k], v)
        else:
            merged[k] = v
    return merged


def resolve_config() -> Dict[str, Any]:
    yaml_cfg = load_simple_yaml(CONFIG_PATH)
    cfg = deep_merge(DEFAULT_CONFIG, yaml_cfg)
    env_vars = {**load_dotenv(ENV_PATH), **os.environ}

    if "ELEVENLABS_VOICE_ID" in env_vars and env_vars["ELEVENLABS_VOICE_ID"]:
        cfg["elevenlabs"]["voice_id"] = env_vars["ELEVENLABS_VOICE_ID"]
    if "ELEVENLABS_MODEL_ID" in env_vars and env_vars["ELEVENLABS_MODEL_ID"]:
        cfg["elevenlabs"]["model_id"] = env_vars["ELEVENLABS_MODEL_ID"]
    if "STUDIO_FPS" in env_vars:
        cfg["studio"]["fps"] = int(env_vars["STUDIO_FPS"])
    if "STUDIO_SURFACE" in env_vars:
        cfg["theme"]["surface"] = env_vars["STUDIO_SURFACE"]

    return cfg


if __name__ == "__main__":
    resolved = resolve_config()
    if "--json" in sys.argv or len(sys.argv) == 1:
        print(json.dumps(resolved, indent=2, ensure_ascii=False))
    elif "--key" in sys.argv:
        idx = sys.argv.index("--key")
        if idx + 1 < len(sys.argv):
            keys = sys.argv[idx + 1].split(".")
            curr: Any = resolved
            for key in keys:
                curr = curr.get(key, {}) if isinstance(curr, dict) else None
            print(curr if not isinstance(curr, dict) else json.dumps(curr))

/**
 * src/theme/motion.ts
 * Sistema de Movimiento Cerrado, Físicas Spring, Paleta Editorial (Zero-Neon)
 * y Constantes de Zona Segura Vertical (9:16).
 *
 * REGLAS INQUEBRANTABLES:
 * 1. Prohibido CSS transition o @keyframes. Todo movimiento usa useCurrentFrame().
 * 2. Todo interpolate() debe incluir CLAMP_EXTRAPOLATION.
 * 3. Únicamente se permiten dos físicas spring(): SPRING_SNAPPY y SPRING_CAMERA.
 * 4. Política Zero-Neon: Cero resplandores, cero gradientes cian-púrpura, cero cyberpunk.
 * 5. Zona Segura Vertical (9:16): Todo texto y vector clave en el 85% superior (288px inferiores reservados).
 */

import type { SpringConfig } from 'remotion';

/**
 * Física Spring #1: Entradas de UI, iconos lucide-react, tarjetas y trazos roughjs.
 */
export const SPRING_SNAPPY: SpringConfig = {
  damping: 20,
  stiffness: 200,
  mass: 0.8,
  overshootClamping: false,
} as const;

/**
 * Física Spring #2: Movimientos panorámicos y zooms del CameraRig sobre lienzo continuo.
 */
export const SPRING_CAMERA: SpringConfig = {
  damping: 30,
  stiffness: 90,
  mass: 1.2,
  overshootClamping: false,
} as const;

/**
 * Configuración obligatoria para todas las llamadas a interpolate().
 */
export const CLAMP_EXTRAPOLATION = {
  extrapolateLeft: 'clamp',
  extrapolateRight: 'clamp',
} as const;

/**
 * Dimensiones y Zona Segura Vertical (9:16 — Reels / TikTok / Shorts)
 */
export const VIDEO_CONFIG = {
  fps: 30,
  width: 1080,
  height: 1920,
  crossDissolveFrames: 10,
} as const;

export const SAFE_ZONE = {
  /** 85% superior del lienzo disponible para titulares, subtítulos y vectores clave */
  maxSafeY: 1632, // 1920 - 288
  /** 288px inferiores reservados estrictamente para la UI de Reels/TikTok/Shorts */
  bottomReservedPx: 288,
  /** Padding lateral mínimo obligatorio a cada lado */
  horizontalPaddingPx: 96,
  /** Coordenada X mínima y máxima segura */
  minSafeX: 96,
  maxSafeX: 984, // 1080 - 96
  /** Reglas tipográficas mínimas */
  minHeadlinePx: 64,
  maxHeadlineWords: 7,
  minLabelPx: 28,
  maxLabelWords: 20,
} as const;

/**
 * Paleta Editorial Cálida — Política Estricta ZERO-NEON
 * Prohibido box-shadow resplandeciente, text-shadow neón o gradientes cian-púrpura.
 */
export const PALETTE = {
  /** Superficie cálida principal tipo papel técnico */
  surface: '#F8F7F4',
  /** Superficie de tarjeta editorial elevada */
  surfaceElevated: '#FFFFFF',
  /** Superficie secundaria sutil */
  surfaceMuted: '#EFECE6',
  /** Cuadrícula técnica sutil */
  gridLine: '#E5E2DC',
  /** Tinta principal de alto contraste */
  ink: '#141413',
  /** Tinta secundaria para etiquetas y metadatos */
  inkMuted: '#575550',
  /** Acento primario cálido (Terracota / Bermellón técnico) */
  accentPrimary: '#D94E34',
  /** Acento secundario técnico (Azul Cobalto mate) */
  accentSecondary: '#1D4ED8',
  /** Acento de verificación / métrica positiva (Verde bosque mate) */
  accentSuccess: '#15803D',
  /** Acento de advertencia / contraste (Ámbar ocre mate) */
  accentWarning: '#B45309',
  /** Borde técnico para trazos y contenedores */
  border: '#262523',
} as const;

import { z } from 'zod';

/**
 * Presets de personalidad vocal de ElevenLabs mapeados a voice_settings
 */
export const CharacterPresetSchema = z.enum([
  'narrator',
  'expert',
  'dramatic',
  'conversational',
  'calm',
]);

export type CharacterPreset = z.infer<typeof CharacterPresetSchema>;

/**
 * Marca de tiempo palabra por palabra calculada a partir del alignment de ElevenLabs
 */
export const WordTimestampSchema = z.object({
  word: z.string(),
  startMs: z.number(),
  endMs: z.number(),
  startFrame: z.number(),
  endFrame: z.number(),
});

export type WordTimestamp = z.infer<typeof WordTimestampSchema>;

/**
 * Definición de escena en src/data/scenes.json
 */
export const SceneInputSchema = z.object({
  id: z.string(),
  title: z.string(),
  text: z.string(),
  characterPreset: CharacterPresetSchema,
  visualCue: z.string(),
  cameraTarget: z
    .object({
      x: z.number(),
      y: z.number(),
      zoom: z.number().min(0.4).max(3.0),
      rotateDeg: z.number().optional(),
    })
    .optional(),
  metrics: z
    .object({
      label: z.string(),
      numericValue: z.number(),
      unit: z.string(),
    })
    .optional(),
});

export type SceneInput = z.infer<typeof SceneInputSchema>;

export const ScenesFileSchema = z.object({
  projectTitle: z.string(),
  fps: z.number().default(30),
  width: z.number().default(1080),
  height: z.number().default(1920),
  crossDissolveFrames: z.number().default(10),
  scenes: z.array(SceneInputSchema),
});

export type ScenesFile = z.infer<typeof ScenesFileSchema>;

/**
 * Metadatos de sincronización generados por scripts/elevenlabs-sync.mjs en public/audio/info.json
 */
export const SceneAudioInfoSchema = z.object({
  id: z.string(),
  audioFile: z.string(),
  characterPreset: CharacterPresetSchema,
  actualDuration: z.number(),
  durationInFrames: z.number(),
  wordsPerSecond: z.number(),
  leadingSilenceMs: z.number(),
  trailingSilenceMs: z.number(),
  trimOffsetMs: z.number().default(0),
  warnings: z.array(z.string()).default([]),
  wordTimestamps: z.array(WordTimestampSchema),
});

export type SceneAudioInfo = z.infer<typeof SceneAudioInfoSchema>;

export const AudioManifestSchema = z.object({
  generatedAt: z.string(),
  fps: z.number(),
  crossDissolveFrames: z.number(),
  totalDurationInFrames: z.number(),
  totalDurationSeconds: z.number(),
  backgroundMusicFile: z.string().nullable().default(null),
  scenes: z.array(SceneAudioInfoSchema),
});

export type AudioManifest = z.infer<typeof AudioManifestSchema>;

/**
 * Props parametrizables del componente principal <Video />
 */
export const VideoPropsSchema = z.object({
  title: z.string().default('Diagnóstico Estudio Vectorial Antigravity'),
  surfaceColor: z.string().default('#F8F7F4'),
  enableCaptions: z.boolean().default(true),
  enableBackgroundMusic: z.boolean().default(false),
});

export type VideoProps = z.infer<typeof VideoPropsSchema>;

