import React from 'react';
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from 'remotion';
import {
  CLAMP_EXTRAPOLATION,
  PALETTE,
  SPRING_CAMERA,
} from '../theme/motion';

export interface CameraKeyframe {
  frame: number;
  x: number;
  y: number;
  zoom: number;
  rotateDeg?: number;
}

export interface CameraRigProps {
  keyframes: CameraKeyframe[];
  surfaceColor?: string;
  children: React.ReactNode;
}

/**
 * CameraRig — Aparejo de Cámara Continua sobre Lienzo Único
 * Impulsado exclusivamente por SPRING_CAMERA ({ damping: 30, stiffness: 90, mass: 1.2 })
 * y useCurrentFrame(). Cero CSS transitions.
 */
export const CameraRig: React.FC<CameraRigProps> = ({
  keyframes,
  surfaceColor = PALETTE.surface,
  children,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  let currentX = keyframes[0]?.x ?? 0;
  let currentY = keyframes[0]?.y ?? 0;
  let currentZoom = keyframes[0]?.zoom ?? 1;
  let currentRotate = keyframes[0]?.rotateDeg ?? 0;

  for (let i = 1; i < keyframes.length; i++) {
    const prev = keyframes[i - 1];
    const next = keyframes[i];
    if (frame >= prev.frame) {
      const progress = spring({
        frame: frame - prev.frame,
        fps,
        config: SPRING_CAMERA,
      });

      currentX = interpolate(progress, [0, 1], [currentX, next.x], CLAMP_EXTRAPOLATION);
      currentY = interpolate(progress, [0, 1], [currentY, next.y], CLAMP_EXTRAPOLATION);
      currentZoom = interpolate(
        progress,
        [0, 1],
        [currentZoom, next.zoom],
        CLAMP_EXTRAPOLATION
      );
      currentRotate = interpolate(
        progress,
        [0, 1],
        [currentRotate, next.rotateDeg ?? 0],
        CLAMP_EXTRAPOLATION
      );
    }
  }

  return (
    <AbsoluteFill
      style={{
        backgroundColor: surfaceColor,
        overflow: 'hidden',
      }}
    >
      {/* Cuadrícula técnica editorial sutil (Zero-Neon) */}
      <svg
        width={width}
        height={height}
        style={{
          position: 'absolute',
          inset: 0,
          pointerEvents: 'none',
        }}
      >
        <defs>
          <pattern
            id="editorial-grid"
            width={72}
            height={72}
            patternUnits="userSpaceOnUse"
            patternTransform={`translate(${-currentX * 0.25}, ${-currentY * 0.25})`}
          >
            <path
              d="M 72 0 L 0 0 0 72"
              fill="none"
              stroke={PALETTE.gridLine}
              strokeWidth={1.5}
            />
          </pattern>
        </defs>
        <rect width={width} height={height} fill="url(#editorial-grid)" />
      </svg>

      {/* Lienzo continuo transformado matemáticamente */}
      <div
        style={{
          position: 'absolute',
          width: '100%',
          height: '100%',
          transformOrigin: `${width / 2}px ${height / 2}px`,
          transform: `translate3d(${-currentX}px, ${-currentY}px, 0) scale(${currentZoom}) rotate(${currentRotate}deg)`,
        }}
      >
        {children}
      </div>
    </AbsoluteFill>
  );
};

import React, { useMemo } from 'react';
import rough from 'roughjs';
import { interpolate, spring, useCurrentFrame, useVideoConfig } from 'remotion';
import {
  CLAMP_EXTRAPOLATION,
  PALETTE,
  SPRING_SNAPPY,
} from '../theme/motion';

export interface RoughCardProps {
  width: number;
  height: number;
  enterFrame?: number;
  strokeColor?: string;
  fillColor?: string;
  accentColor?: string;
  seed?: number;
  roughness?: number;
  children?: React.ReactNode;
}

/**
 * RoughCard — Contenedor vectorial editorial con trazos generados determinísticamente por roughjs
 * y física de entrada SPRING_SNAPPY.
 */
export const RoughCard: React.FC<RoughCardProps> = ({
  width,
  height,
  enterFrame = 0,
  strokeColor = PALETTE.border,
  fillColor = PALETTE.surfaceElevated,
  accentColor = PALETTE.accentPrimary,
  seed = 42,
  roughness = 1.15,
  children,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const entrance = spring({
    frame: frame - enterFrame,
    fps,
    config: SPRING_SNAPPY,
  });

  const scale = interpolate(entrance, [0, 1], [0.92, 1], CLAMP_EXTRAPOLATION);
  const opacity = interpolate(entrance, [0, 0.5, 1], [0, 1, 1], CLAMP_EXTRAPOLATION);
  const translateY = interpolate(entrance, [0, 1], [28, 0], CLAMP_EXTRAPOLATION);

  const roughPaths = useMemo(() => {
    const generator = rough.generator();
    const drawable = generator.rectangle(6, 6, width - 12, height - 12, {
      seed,
      roughness,
      bowing: 0.9,
      stroke: strokeColor,
      strokeWidth: 3.5,
      fill: fillColor,
      fillStyle: 'solid',
    });
    const accentBar = generator.line(18, 18, width - 18, 18, {
      seed: seed + 7,
      roughness: 0.8,
      stroke: accentColor,
      strokeWidth: 5,
    });
    return {
      rectPaths: generator.toPaths(drawable),
      accentPaths: generator.toPaths(accentBar),
    };
  }, [width, height, seed, roughness, strokeColor, fillColor, accentColor]);

  return (
    <div
      style={{
        position: 'relative',
        width,
        height,
        opacity,
        transform: `translateY(${translateY}px) scale(${scale})`,
      }}
    >
      <svg
        width={width}
        height={height}
        style={{
          position: 'absolute',
          inset: 0,
          overflow: 'visible',
        }}
      >
        {roughPaths.rectPaths.map((p, idx) => (
          <path
            key={`rect-${idx}`}
            d={p.d}
            stroke={p.stroke}
            strokeWidth={p.strokeWidth}
            fill={p.fill || 'none'}
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        ))}
        {roughPaths.accentPaths.map((p, idx) => (
          <path
            key={`accent-${idx}`}
            d={p.d}
            stroke={p.stroke}
            strokeWidth={p.strokeWidth}
            fill="none"
            strokeLinecap="round"
          />
        ))}
      </svg>
      <div
        style={{
          position: 'relative',
          width: '100%',
          height: '100%',
          padding: '38px 36px 32px 36px',
          boxSizing: 'border-box',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'space-between',
        }}
      >
        {children}
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { createTikTokStyleCaptions, type Caption } from '@remotion/captions';
import { interpolate, spring, useCurrentFrame, useVideoConfig } from 'remotion';
import type { WordTimestamp } from '../data/schema';
import {
  CLAMP_EXTRAPOLATION,
  PALETTE,
  SAFE_ZONE,
  SPRING_SNAPPY,
} from '../theme/motion';

export interface DynamicCaptionsProps {
  wordTimestamps: WordTimestamp[];
  /** Offset global en fotogramas donde arranca esta escena */
  sceneStartFrame?: number;
}

/**
 * DynamicCaptions — Subtítulos dinámicos palabra por palabra compatibles con @remotion/captions
 * Posicionados estrictamente dentro del 85% superior del lienzo (SAFE_ZONE.maxSafeY = 1632px).
 */
export const DynamicCaptions: React.FC<DynamicCaptionsProps> = ({
  wordTimestamps,
  sceneStartFrame = 0,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const localFrame = frame - sceneStartFrame;
  const currentTimeMs = (localFrame / fps) * 1000;

  const pages = useMemo(() => {
    if (!wordTimestamps || wordTimestamps.length === 0) {
      return [];
    }
    const captions: Caption[] = wordTimestamps.map((w, index) => ({
      text: index === 0 ? w.word : ` ${w.word}`,
      startMs: w.startMs,
      endMs: w.endMs,
      timestampMs: w.startMs,
      confidence: 1,
    }));

    const { pages: tiktokPages } = createTikTokStyleCaptions({
      captions,
      combineTokensWithinMilliseconds: 950,
    });
    return tiktokPages;
  }, [wordTimestamps]);

  const activePage = useMemo(() => {
    return pages.find((page, idx) => {
      const nextPage = pages[idx + 1];
      const pageEndMs = nextPage
        ? nextPage.startMs
        : (page.tokens[page.tokens.length - 1]?.toMs ?? page.startMs + 1200) + 250;
      return currentTimeMs >= page.startMs - 60 && currentTimeMs <= pageEndMs;
    });
  }, [pages, currentTimeMs]);

  if (!activePage) {
    return null;
  }

  const pageStartFrame = Math.floor((activePage.startMs / 1000) * fps);
  const pageEntrance = spring({
    frame: localFrame - pageStartFrame,
    fps,
    config: SPRING_SNAPPY,
  });

  const translateY = interpolate(pageEntrance, [0, 1], [14, 0], CLAMP_EXTRAPOLATION);

  return (
    <div
      style={{
        position: 'absolute',
        left: SAFE_ZONE.horizontalPaddingPx,
        right: SAFE_ZONE.horizontalPaddingPx,
        top: SAFE_ZONE.maxSafeY - 196,
        maxHeight: 170,
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        pointerEvents: 'none',
        transform: `translateY(${translateY}px)`,
      }}
    >
      <div
        style={{
          backgroundColor: PALETTE.surfaceElevated,
          border: `3px solid ${PALETTE.border}`,
          borderRadius: 18,
          padding: '18px 28px',
          display: 'flex',
          flexWrap: 'wrap',
          justifyContent: 'center',
          gap: '10px 12px',
          maxWidth: SAFE_ZONE.maxSafeX - SAFE_ZONE.minSafeX,
        }}
      >
        {activePage.tokens.map((token, idx) => {
          const isActive =
            currentTimeMs >= token.fromMs - 30 && currentTimeMs <= token.toMs + 60;
          const tokenStartFrame = Math.floor((token.fromMs / 1000) * fps);
          const tokenPop = spring({
            frame: localFrame - tokenStartFrame,
            fps,
            config: SPRING_SNAPPY,
          });
          const scale = isActive
            ? interpolate(tokenPop, [0, 1], [0.94, 1.06], CLAMP_EXTRAPOLATION)
            : 1;

          return (
            <span
              key={`${token.fromMs}-${idx}`}
              style={{
                display: 'inline-block',
                fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
                fontSize: 38,
                fontWeight: 800,
                lineHeight: 1.2,
                letterSpacing: '-0.02em',
                color: isActive ? PALETTE.surfaceElevated : PALETTE.ink,
                backgroundColor: isActive ? PALETTE.accentPrimary : 'transparent',
                padding: isActive ? '2px 12px' : '2px 4px',
                borderRadius: 10,
                transform: `scale(${scale})`,
              }}
            >
              {token.text.trim()}
            </span>
          );
        })}
      </div>
    </div>
  );
};

